import os
import json
import asyncio
import uuid
from datetime import datetime
from typing import Dict, List, Optional
from collections import defaultdict

from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa

 ============================================================================
 INICIALIZÁLÁS
 ============================================================================

app = Flask(__name__, static_folder='static')
CORS(app)

 API kulcsok  az Ön kulcsai a környezeti változókból
CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")
EXA_API_KEY = os.getenv("EXA_API_KEY")

if not CEREBRAS_API_KEY or not EXA_API_KEY:
    raise ValueError("CEREBRAS_API_KEY és EXA_API_KEY környezeti változók beállítása kötelező!")

cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
exa_client = Exa(api_key=EXA_API_KEY)

 Globális tárolók
chat_histories: Dict[str, List[dict]] = defaultdict(list)
research_tasks: Dict[str, dict] = {}

 Modellek
CHAT_MODEL = "llama3.170b"
RESEARCH_MODEL = "llama3.170b"

 ============================================================================
 CHAT HISTORY KEZELÉS
 ============================================================================

@app.route('/api/chat/history/<session_id>', methods=['GET'])
def get_chat_history(session_id: str):
    """Beszélgetési előzmények lekérése"""
    messages = chat_histories.get(session_id, [])
    return jsonify({"messages": messages})

@app.route('/api/chat/history/<session_id>', methods=['POST'])
def save_chat_message(session_id: str):
    """Üzenet mentése a beszélgetési előzményekbe"""
    data = request.json
    message = data.get('message', {})

    if message:
        chat_histories[session_id].append(message)

    return jsonify({"success": True})

@app.route('/api/chat/history/<session_id>', methods=['DELETE'])
def clear_chat_history(session_id: str):
    """Beszélgetési előzmények törlése"""
    if session_id in chat_histories:
        del chat_histories[session_id]

    return jsonify({"success": True})

 ============================================================================
 CHAT VÉGPONT
 ============================================================================

@app.route('/api/chat', methods=['POST'])
def chat():
    """Fő chat végpont  beszélgetés az AIval"""
    try:
        data = request.json
        messages = data.get('messages', [])
        temperature = data.get('temperature', 0.7)

        if not messages:
            return jsonify({"error": "Nincs üzenet megadva"}), 400

         Cerebras API hívás
        response = cerebras_client.chat.completions.create(
            model=CHAT_MODEL,
            messages=messages,
            temperature=temperature,
            max_tokens=2048
        )

        return jsonify({
            "choices": [{
                "message": {
                    "role": "assistant",
                    "content": response.choices[0].message.content
                }
            }]
        })

    except Exception as e:
        print(f"Chat hiba: {str(e)}")
        return jsonify({"error": f"Hiba történt: {str(e)}"}), 500

 ============================================================================
 KUTATÁSI FELADAT LÉTREHOZÁSA
 ============================================================================

@app.route('/api/research/create', methods=['POST'])
def create_research():
    """Új kutatási feladat indítása"""
    try:
        data = request.json
        task_id = str(uuid.uuid4())

         Feladat adatok
        research_tasks[task_id] = {
            "id": task_id,
            "goal": data.get('goal', ''),
            "status": "Indítás...",
            "progress": 0,
            "sub_agents": [
                {"name": "Keresési Ágent", "status": "Várakozás..."},
                {"name": "Elemző Ágent", "status": "Várakozás..."},
                {"name": "Jelentés Író Ágent", "status": "Várakozás..."}
            ],
            "sources": [],
            "report": "",
            "search_params": {
                "search_type": data.get('search_type', 'auto'),
                "category": data.get('category'),
                "user_location": data.get('user_location'),
                "start_published_date": data.get('start_published_date'),
                "end_published_date": data.get('end_published_date'),
                "start_crawl_date": data.get('start_crawl_date'),
                "end_crawl_date": data.get('end_crawl_date'),
                "include_domains": data.get('include_domains'),
                "exclude_domains": data.get('exclude_domains'),
                "include_text": data.get('include_text'),
                "exclude_text": data.get('exclude_text'),
                "full_text": data.get('full_text', False),
                "ai_summary": data.get('ai_summary', False),
                "subpages": data.get('subpages', False),
                "subpage_target": data.get('subpage_target', 3),
                "livecrawl": data.get('livecrawl', 'fallback'),
                "livecrawl_timeout": data.get('livecrawl_timeout'),
                "links": data.get('links', False)
            }
        }

         Aszinkron kutatás indítása háttérben
        asyncio.create_task(run_research_task(task_id))

        return jsonify({"task_id": task_id})

    except Exception as e:
        print(f"Kutatás létrehozási hiba: {str(e)}")
        return jsonify({"error": str(e)}), 500

