 ============================================================================

@app.route('/api/research/<task_id>', methods=['GET'])
def get_research_status(task_id: str):
    """Kutatási feladat státuszának lekérése"""
    task = research_tasks.get(task_id)

    if not task:
        return jsonify({"error": "Feladat nem található"}), 404

    return jsonify(task)

 ============================================================================
 KUTATÁSI FOLYAMAT
 ============================================================================

async def run_research_task(task_id: str):
    """Kutatási feladat futtatása"""
    task = research_tasks[task_id]

    try:
         1. FÁZIS: Keresési lekérdezések generálása
        task["status"] = "Keresési lekérdezések generálása..."
        task["progress"] = 10
        task["sub_agents"][0]["status"] = "Aktív"

        queries = await generate_search_queries(task["goal"])

         2. FÁZIS: Web keresés
        task["status"] = "Web keresés folyamatban..."
        task["progress"] = 30
        task["sub_agents"][0]["status"] = "Web források gyűjtése..."

        sources = await search_web(queries, task["search_params"])
        task["sources"] = sources

        task["sub_agents"][0]["status"] = "Befejezve"

         3. FÁZIS: Tartalom elemzése
        task["status"] = "Tartalom elemzése..."
        task["progress"] = 60
        task["sub_agents"][1]["status"] = "Aktív  Források feldolgozása..."

        analyzed_content = await analyze_sources(sources, task["goal"])

        task["sub_agents"][1]["status"] = "Befejezve"

         4. FÁZIS: Jelentés írása
        task["status"] = "Jelentés készítése..."
        task["progress"] = 80
        task["sub_agents"][2]["status"] = "Aktív  Jelentés írása..."

        report = await generate_report(task["goal"], analyzed_content, sources)
        task["report"] = report

        task["sub_agents"][2]["status"] = "Befejezve"

         BEFEJEZÉS
        task["status"] = "completed"
        task["progress"] = 100

    except Exception as e:
        print(f"Kutatási hiba: {str(e)}")
        task["status"] = "error"
        task["report"] = f"Hiba történt: {str(e)}"

async def generate_search_queries(goal: str) > List[str]:
    """Keresési lekérdezések generálása AIval"""
    try:
        prompt = f"""Generálj 35 precíz keresési lekérdezést a következő kutatási célhoz:

Kutatási cél: {goal}

Adj vissza csak a lekérdezéseket, soronként egyet, magyarázat nélkül."""

        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.7,
            max_tokens=500
        )

        queries_text = response.choices[0].message.content
        queries = [q.strip() for q in queries_text.split('\n') if q.strip() and not q.strip().startswith('')]

        return queries[:5]

    except Exception as e:
        print(f"Lekérdezés generálási hiba: {str(e)}")
        return [goal]

async def search_web(queries: List[str], search_params: dict) > List[dict]:
    """Web keresés Exa APIval"""
    all_sources = []

    try:
        for query in queries:
             Exa keresési paraméterek összeállítása
            search_kwargs = {
                "query": query,
                "num_results": 10,
                "use_autoprompt": True,
                "type": search_params.get("search_type", "auto")
            }

             Opcionális paraméterek hozzáadása
            if search_params.get("category"):
                search_kwargs["category"] = search_params["category"]

            if search_params.get("start_published_date"):
                search_kwargs["start_published_date"] = search_params["start_published_date"]

            if search_params.get("end_published_date"):
                search_kwargs["end_published_date"] = search_params["end_published_date"]

            if search_params.get("include_domains"):
                search_kwargs["include_domains"] = search_params["include_domains"]

            if search_params.get("exclude_domains"):
                search_kwargs["exclude_domains"] = search_params["exclude_domains"]

             Tartalom opciók
            contents_kwargs = {
                "text": True if search_params.get("full_text") else {"max_characters": 1000},
                "highlights": True
            }

            if search_params.get("ai_summary"):
                contents_kwargs["summary"] = True

             Keresés végrehajtása
            results = exa_client.search_and_contents(search_kwargs, contents_kwargs)

             Eredmények feldolgozása
            for result in results.results:
                source = {
                    "url": result.url,
                    "title": result.title,
                    "text": result.text if hasattr(result, 'text') else "",
                    "summary": result.summary if hasattr(result, 'summary') else "",
                    "published_date": result.published_date if hasattr(result, 'published_date') else None
                }
                all_sources.append(source)

         Duplikációk eltávolítása URL alapján
        seen_urls = set()
        unique_sources = []
        for source in all_sources:
            if source["url"] not in seen_urls:
                seen_urls.add(source["url"])
                unique_sources.append(source)

        return unique_sources[:30]   Maximum 30 forrás

    except Exception as e:
        print(f"Web keresési hiba: {str(e)}")
        return []

async def analyze_sources(sources: List[dict], goal: str) > str:
    """Források elemzése és összegzése"""
    try:
         Források szövegeinek összeállítása
        sources_text = ""
        for i, source in enumerate(sources[:15], 1):   Első 15 forrás
            text = source.get("text", "") or source.get("summary", "")
            if text:
                sources_text += f"\n\n FORRÁS {i}: {source['title']} \n{text[:2000]}"

        prompt = f"""Elemezd az alábbi forrásokat a következő kutatási cél alapján:

Kutatási cél: {goal}

Források:
{sources_text}

Add meg a legfontosabb megállapításokat, tényeket és összefüggéseket strukturáltan."""

        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.5,
            max_tokens=3000
        )

        return response.choices[0].message.content

    except Exception as e:
        print(f"Elemzési hiba: {str(e)}")
        return "Nem sikerült elemezni a forrásokat."

async def generate_report(goal: str, analyzed_content: str, sources: List[dict]) > str:
    """Részletes jelentés generálása"""
    try:
         Forráslisták készítése
        sources_list = "\n".join([
            f"[{i}] {s['title']}  {s['url']}" 
            for i, s in enumerate(sources[:20], 1)
        ])

        prompt = f"""Készíts részletes, szakmai kutatási jelentést az alábbi adatok alapján:

KUTATÁSI CÉL:
{goal}

ELEMZETT TARTALOM:
{analyzed_content}

FORRÁSOK:
{sources_list}

A jelentés legyen:
 Strukturált fejezetekkel
 Minimum 800 szó
 Tartalmazza a legfontosabb megállapításokat
 Konkrét adatokat és tényeket
 Következtetéseket és ajánlásokat
 Magyar nyelven
 Szakmai stílusban

A jelentés végén add meg a használt forrásokat számozott hivatkozásként."""

        response = cerebras_client.chat.completions.create(
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.6,
            max_tokens=4000
        )

        return response.choices[0].message.content

    except Exception as e:
        print(f"Jelentés generálási hiba: {str(e)}")
        return "Nem sikerült generálni a jelentést."

