python
import os
import asyncio
import uuid
import threading
from typing import Dict, List
from collections import defaultdict
from flask import Flask, request, jsonify
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa

app = Flask(__name__, static_folder='static')
CORS(app)

CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")
EXA_API_KEY = os.getenv("EXA_API_KEY")

if not CEREBRAS_API_KEY or not EXA_API_KEY:
    raise ValueError("CEREBRAS_API_KEY és EXA_API_KEY környezeti változók beállítása kötelező!")

cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
exa_client = Exa(api_key=EXA_API_KEY)

chat_histories: Dict[str, List[dict]] = defaultdict(list)
research_tasks: Dict[str, dict] = {}

CHAT_MODEL = "llama3.1-70b"
RESEARCH_MODEL = "llama3.1-70b"

research_loop = asyncio.new_event_loop()
def _start_loop(loop: asyncio.AbstractEventLoop) -> None:
    asyncio.set_event_loop(loop)
    loop.run_forever()
loop_thread = threading.Thread(target=_start_loop, args=(research_loop,), daemon=True)
loop_thread.start()

async def _to_thread(func, *args, **kwargs):
    return await asyncio.to_thread(func, *args, **kwargs)

@app.route('/api/chat/history/<session_id>', methods=['GET'])
def get_chat_history(session_id: str):
    messages = chat_histories.get(session_id, [])
    return jsonify({"messages": messages})

@app.route('/api/chat/history/<session_id>', methods=['POST'])
def save_chat_message(session_id: str):
    data = request.json or {}
    message = data.get('message', {})
    if message:
        chat_histories[session_id].append(message)
    return jsonify({"success": True})

@app.route('/api/chat/history/<session_id>', methods=['DELETE'])
def clear_chat_history(session_id: str):
    if session_id in chat_histories:
        del chat_histories[session_id]
    return jsonify({"success": True})

@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        data = request.json or {}
        messages = data.get('messages', [])
        temperature = data.get('temperature', 0.7)
        if not isinstance(messages, list) or not messages:
            return jsonify({"error": "Nincs üzenet megadva"}), 400
        response = cerebras_client.chat.completions.create(
            model=CHAT_MODEL,
            messages=messages,
            temperature=float(temperature),
            max_tokens=2048
        )
        return jsonify({
            "choices": [{
                "message": {
                    "role": "assistant",
                    "content": response.choices[0].message.content
                }
            }]
        })
    except Exception as e:
        return jsonify({"error": f"Hiba történt: {str(e)}"}), 500

@app.route('/api/research/create', methods=['POST'])
def create_research():
    try:
        data = request.json or {}
        task_id = str(uuid.uuid4())
        research_tasks[task_id] = {
            "id": task_id,
            "goal": data.get('goal', ''),
            "status": "Keresési lekérdezések előkészítése...",
            "progress": 0,
            "sub_agents": [
                {"name": "Keresési Ágens", "status": "Várakozás..."},
                {"name": "Elemző Ágens", "status": "Várakozás..."},
                {"name": "Jelentésíró Ágens", "status": "Várakozás..."}
            ],
            "sources": [],
            "report": "",
            "search_params": {
                "search_type": data.get('search_type', 'auto'),
                "category": data.get('category'),
                "user_location": data.get('user_location'),
                "start_published_date": data.get('start_published_date'),
                "end_published_date": data.get('end_published_date'),
                "start_crawl_date": data.get('start_crawl_date'),
                "end_crawl_date": data.get('end_crawl_date'),
                "include_domains": data.get('include_domains'),
                "exclude_domains": data.get('exclude_domains'),
                "include_text": data.get('include_text'),
                "exclude_text": data.get('exclude_text'),
                "full_text": bool(data.get('full_text', False)),
                "ai_summary": bool(data.get('ai_summary', False)),
                "subpages": bool(data.get('subpages', False)),
                "subpage_target": int(data.get('subpage_target', 3)) if isinstance(data.get('subpage_target', 3), int) else 3,
                "livecrawl": data.get('livecrawl', 'fallback'),
                "livecrawl_timeout": data.get('livecrawl_timeout'),
                "links": bool(data.get('links', False))
            }
        }
        asyncio.run_coroutine_threadsafe(run_research_task(task_id), research_loop)
        return jsonify({"task_id": task_id})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/research/<task_id>', methods=['GET'])
def get_research_status(task_id: str):
    task = research_tasks.get(task_id)
    if not task:
        return jsonify({"error": "Feladat nem található"}), 404
    return jsonify(task)

async def run_research_task(task_id: str):
    task = research_tasks.get(task_id)
    if not task:
        return
    try:
        task["status"] = "Keresési lekérdezések generálása..."
        task["progress"] = 10
        task["sub_agents"][0]["status"] = "Aktív"
        queries = await generate_search_queries(task["goal"])
        task["status"] = "Webes források keresése..."
        task["progress"] = 30
        task["sub_agents"][0]["status"] = "Web források gyűjtése..."
        sources = await perform_search(queries, task["search_params"])
        task["sources"] = sources
        task["sub_agents"][0]["status"] = "Befejezve"
        task["status"] = "Tartalom elemzése..."
        task["progress"] = 60
        task["sub_agents"][1]["status"] = "Aktív - Források feldolgozása..."
        analyzed_content = await analyze_sources(sources, task["goal"])
        task["sub_agents"][1]["status"] = "Befejezve"
        task["status"] = "Jelentés készítése..."
        task["progress"] = 80
        task["sub_agents"][2]["status"] = "Aktív - Jelentés írása..."
        report = await generate_report(task["goal"], analyzed_content, sources)
        task["report"] = report
        task["sub_agents"][2]["status"] = "Befejezve"
        task["status"] = "completed"
        task["progress"] = 100
    except Exception as e:
        task["status"] = "error"
        task["report"] = f"Hiba történt: {str(e)}"

async def generate_search_queries(goal: str) -> List[str]:
    try:
        prompt = f"Generálj 3-5 precíz keresési lekérdezést a következő kutatási célhoz:\n\nKutatási cél: {goal}\n\nAdj vissza csak a lekérdezéseket, soronként egyet, magyarázat nélkül."
        response = await _to_thread(
            cerebras_client.chat.completions.create,
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.7,
            max_tokens=500
        )
        queries_text = response.choices[0].message.content or ""
        queries = [q.strip() for q in queries_text.split('\n') if q.strip() and not q.strip().startswith('#')]
        if not queries:
            return [goal.strip()] if goal.strip() else []
        return queries[:5]
    except Exception:
        return [goal.strip()] if goal.strip() else []

async def perform_search(queries: List[str], search_params: dict) -> List[dict]:
    all_sources: List[dict] = []
    try:
        for query in queries:
            search_kwargs = {
                "query": query,
                "num_results": 10,
                "use_autoprompt": True,
                "type": search_params.get("search_type", "auto")
            }
            if search_params.get("category"):
                search_kwargs["category"] = search_params["category"]
            if search_params.get("user_location"):
                search_kwargs["user_location"] = search_params["user_location"]
            if search_params.get("start_published_date"):
                search_kwargs["start_published_date"] = search_params["start_published_date"]
            if search_params.get("end_published_date"):
                search_kwargs["end_published_date"] = search_params["end_published_date"]
            if search_params.get("start_crawl_date"):
                search_kwargs["start_crawl_date"] = search_params["start_crawl_date"]
            if search_params.get("end_crawl_date"):
                search_kwargs["end_crawl_date"] = search_params["end_crawl_date"]
            if search_params.get("include_domains"):
                search_kwargs["include_domains"] = search_params["include_domains"]
            if search_params.get("exclude_domains"):
                search_kwargs["exclude_domains"] = search_params["exclude_domains"]
            text_opt = True if search_params.get("full_text") else {"max_characters": 1000}
            highlights_opt = True
            summary_opt = bool(search_params.get("ai_summary", False))
            livecrawl_opt = search_params.get("livecrawl", "fallback")
            if livecrawl_opt not in ("always", "fallback", "never"):
                livecrawl_opt = "fallback"
            results = await _to_thread(
                exa_client.search_and_contents,
                text=text_opt,
                highlights=highlights_opt,
                summary=summary_opt,
                livecrawl=livecrawl_opt,
                **search_kwargs
            )
            for result in getattr(results, "results", []):
                url = getattr(result, "url", None)
                title = getattr(result, "title", None)
                text_val = getattr(result, "text", None)
                summary_val = getattr(result, "summary", None)
                published = getattr(result, "published_date", None)
                if url and title:
                    all_sources.append({
                        "url": url,
                        "title": title,
                        "text": text_val if isinstance(text_val, str) else "",
                        "summary": summary_val if isinstance(summary_val, str) else "",
                        "published_date": published
                    })
        seen_urls = set()
        unique_sources = []
        for source in all_sources:
            u = source.get("url")
            if u and u not in seen_urls:
                seen_urls.add(u)
                unique_sources.append(source)
        return unique_sources[:30]
    except Exception:
        return []

async def analyze_sources(sources: List[dict], goal: str) -> str:
    try:
        sources_text_parts: List[str] = []
        idx = 1
        for source in sources[:15]:
            title = source.get("title", "").strip()
            text = (source.get("text", "") or source.get("summary", "")).strip()
            if text:
                snippet = text[:2000]
                sources_text_parts.append(f"--- FORRÁS {idx}: {title} ---\n{snippet}")
                idx += 1
        sources_text = "\n\n".join(sources_text_parts)
        prompt = f"Elemezd az alábbi forrásokat a következő kutatási cél alapján:\n\nKutatási cél: {goal}\n\nForrások:\n{sources_text}\n\nAdd meg a legfontosabb megállapításokat, tényeket és összefüggéseket strukturáltan."
        response = await _to_thread(
            cerebras_client.chat.completions.create,
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.5,
            max_tokens=3000
        )
        return response.choices[0].message.content or ""
    except Exception:
        return "Nem sikerült elemezni a forrásokat."

async def generate_report(goal: str, analyzed_content: str, sources: List[dict]) -> str:
    try:
        sources_list = "\n".join([
            f"[{i}] {s.get('title','')} - {s.get('url','')}"
            for i, s in enumerate(sources[:20], 1)
        ])
        prompt = (
            "Készíts részletes, szakmai kutatási jelentést az alábbi adatok alapján:\n\n"
            f"KUTATÁSI CÉL:\n{goal}\n\n"
            f"ELEMZETT TARTALOM:\n{analyzed_content}\n\n"
            f"FORRÁSOK:\n{sources_list}\n\n"
            "A jelentés legyen:\n"
            "- Strukturált fejezetekkel\n"
            "- Minimum 800 szó\n"
            "- Tartalmazza a legfontosabb megállapításokat\n"
            "- Konkrét adatokat és tényeket\n"
            "- Következtetéseket és ajánlásokat\n"
            "- Magyar nyelven\n"
            "- Szakmai stílusban\n\n"
            "A jelentés végén add meg a használt forrásokat számozott hivatkozásként."
        )
        response = await _to_thread(
            cerebras_client.chat.completions.create,
            model=RESEARCH_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.6,
            max_tokens=4000
        )
        return response.choices[0].message.content or ""
    except Exception:
        return "Nem sikerült generálni a jelentést."

